let registrationMode='signin',registrationBusy=false;
function switchAuth(mode){registrationMode=mode;const signup=mode==='signup';document.getElementById('registrationFields').hidden=!signup;document.getElementById('cloudSignIn').hidden=signup;document.getElementById('cloudSignUp').hidden=!signup;document.getElementById('cloudPassword').autocomplete=signup?'new-password':'current-password';document.getElementById('showSignIn').classList.toggle('active',!signup);document.getElementById('showSignUp').classList.toggle('active',signup);document.getElementById('authIntroduction').textContent=t(signup?'צרו חשבון כדי להצטרף לבית הספר ולכיתה שלכם.':'היכנסו כדי לראות את הכיתה שלכם.')}
function parseInvite(value){const raw=value.trim();if(!raw)return null;const token=/^[0-9a-f-]{36}$/i.test(raw)?raw:raw.match(/#invite=([0-9a-f-]{36})$/i)?.[1];if(!token)throw new Error(t('קוד ההזמנה אינו תקין.'));return token}
function validateRegistration(data){if(!data.name.trim())throw new Error(t('מלאו שם מלא.'));if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email))throw new Error(t('מלאו אימייל תקין.'));if(data.password.length<8)throw new Error(t('הסיסמה צריכה להכיל לפחות 8 תווים.'));if(data.password!==data.confirm)throw new Error(t('הסיסמאות אינן תואמות.'));return{email:data.email.trim(),password:data.password,name:data.name.trim(),invite:parseInvite(data.invite)}}
document.getElementById('showSignIn').onclick=()=>switchAuth('signin');document.getElementById('showSignUp').onclick=()=>switchAuth('signup');
document.getElementById('cloudSignUp').onclick=async()=>{if(registrationBusy)return;if(!cloud.client){cloudMessage(t('הרשמה אמיתית דורשת חיבור Supabase. לא נוצר חשבון בהדגמה.'));return}try{const data=validateRegistration({email:document.getElementById('cloudEmail').value.trim(),password:document.getElementById('cloudPassword').value,confirm:document.getElementById('cloudPasswordConfirm').value,name:document.getElementById('cloudDisplayName').value,invite:document.getElementById('registrationInvite').value});registrationBusy=true;document.getElementById('cloudSignUp').disabled=true;if(data.invite)sessionStorage.setItem('pendingSchoolInvite',data.invite);const result=await cloudResult(cloud.client.auth.signUp({email:data.email,password:data.password,options:{data:{display_name:data.name},emailRedirectTo:location.origin+(data.invite?'#invite='+data.invite:'')}}));document.getElementById('cloudPassword').value='';document.getElementById('cloudPasswordConfirm').value='';if(result.session){cloud.user=result.user;await redeemPendingInvitation();await cloudRefresh();document.getElementById('appContent').hidden=false}else{cloudMessage(t('בדקו את האימייל ואשרו את הכתובת. לאחר האישור היכנסו עם אותו אימייל.'));switchAuth('signin')}}catch(e){cloudMessage(t('ההרשמה לא הושלמה: ')+e.message)}finally{registrationBusy=false;document.getElementById('cloudSignUp').disabled=false}};
document.getElementById('forgotPassword').onclick=async()=>{if(!cloud.client){cloudMessage(t('איפוס סיסמה זמין לאחר חיבור Supabase.'));return}const email=document.getElementById('cloudEmail').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){cloudMessage(t('מלאו אימייל תקין.'));return}try{await cloudResult(cloud.client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/reset-password'}));cloudMessage(t('אם הכתובת רשומה במערכת, תקבלו אימייל לאיפוס סיסמה.'))}catch(e){cloudMessage(e.message)}};
document.getElementById('saveRecoveredPassword').onclick=async()=>{if(!cloud.client)return;const password=document.getElementById('newAccountPassword').value,confirm=document.getElementById('confirmAccountPassword').value;if(password.length<8||password!==confirm){cloudMessage(t('הסיסמאות חייבות להיות זהות ולכלול לפחות 8 תווים.'));return}try{await cloudResult(cloud.client.auth.updateUser({password}));document.getElementById('newAccountPassword').value='';document.getElementById('confirmAccountPassword').value='';document.getElementById('passwordRecovery').hidden=true;history.replaceState(null,'','/');const session=await cloudResult(cloud.client.auth.getSession());cloud.user=session.session?.user;await cloudRefresh();document.getElementById('appContent').hidden=false;cloudMessage(t('הסיסמה עודכנה.'))}catch(e){cloudMessage(e.message)}};
const invite=location.hash.match(/^#invite=([0-9a-f-]{36})$/i)?.[1]||sessionStorage.getItem('pendingSchoolInvite');if(invite){document.getElementById('registrationInvite').value=invite;switchAuth('signup')}else switchAuth('signin');
